[ExtensionOf(FormDatasourceStr(DirPartyQuickCreateForm, LogisticsElectronicAddressEmail))]
internal final class AVADirPartyQuickCreateFormFrm_LEAEmailDS_Extension
{
}

Method.Source:
/// <summary>
/// designed from N.Freidenberger 14.05.2024
/// </summary>
public void initValue()
{
    next initValue();
    LogisticsElectronicAddress       newLogisticsElectronicAddress   = this.cursor();

    if (element.args().menuItemName() ==  menuItemDisplayStr(AVAsmmBusRelQuickCopy))
    {
        smmBusRelTable                   copySmmBusRelTable = element.args().record();

        LogisticsElectronicAddress       copyLogisticsElectronicAddress  = DirParty::primaryElectronicAddress(copySmmBusRelTable.Party, LogisticsElectronicAddressMethodType::Email);

        newLogisticsElectronicAddress.Locator = copyLogisticsElectronicAddress.Locator;
        element.setElectronicAddressLocation();

    }    

    FormRun  formRun = this.formRun();

    Args   elementArgs = formRun.args();

    if (elementArgs.caller() is FormRun && elementArgs.caller() && elementArgs.parmObject() is FormControl)
    {
        FormControl  callerControler = elementArgs.parmObject() as FormControl;

        if (callerControler.name()  == formControlStr(SalesTable, AVAEDIBuyerContactCreate)
         || callerControler.name()  == formControlStr(SalesTable, AVAContactBtnHeader)
         || callerControler.name()  == formControlStr(SalesTable, AVACContactBtn))
        {
            FormRun             callerFormRun = elementArgs.caller();
            //FormDataSource      ediAddressDS  = callerFormRun.dataSource(formDataSourceStr(SalesTable,AVAEDIAddress));
            FormDataSource      salesTableDS  = callerFormRun.dataSource(formDataSourceStr(SalesTable,SalesTable));
            if (salesTableDS)
            {
                AVAEDIAddress       ediAddress; 
                SalesTable          locSalesTable = salesTableDS.cursor();
                select firstonly ediAddress
                    where ediAddress.RefTableId == locSalesTable.TableId
                       && ediAddress.RefRecId   == locSalesTable.RecId
                       && ediAddress.EDIAddressType == AVAEDIAddressType::Buyer;

                if(ediAddress.RecId)
                {
                    newLogisticsElectronicAddress.Locator  = ediAddress.ContactPersonEmail;

                }
            }
        }

    }   
}
